import numpy as np
import pandas as pd
from lxml import etree
import requests
from urllib.parse import urlparse

def r_read_xml(x, encoding="", *args, as_html=False, options="NOBLANKS", **kwargs):
    """
    Python reproduction of xml2::read_xml.
    Returns an lxml element tree or a custom wrapper object that mimics 
    the behavior of an xml_document.
    """

    # options "NOBLANKS" in R's xml2 corresponds to removing ignorable whitespace.
    # In lxml, we can achieve this by using a parser with remove_blank_text=True.
    parser = etree.XMLParser(remove_blank_text=(options == "NOBLANKS" or "NOBLANKS" in str(options)))

    if as_html:
        parser = etree.HTMLParser(remove_blank_text=(options == "NOBLANKS" or "NOBLANKS" in str(options)))

    # Check if x is an XML string or a path/URL
    if isinstance(x, str) and ('<' in x or '>' in x):
        # Read as raw XML string
        try:
            # R's read_xml treats strings as UTF-8 by default after enc2utf8
            doc = etree.fromstring(x.encode('utf-8'), parser=parser)
            # We wrap in an ElementTree to mimic the 'xml_document' object behavior
            return etree.ElementTree(doc)
        except etree.XMLSyntaxError:
            if as_html:
                # HTML parser is more lenient
                doc = etree.fromstring(x.encode('utf-8'), parser=parser)
                return etree.ElementTree(doc)
            raise
    else:
        # Treat x as a file path or URL
        parsed_url = urlparse(str(x))
        if parsed_url.scheme in ('http', 'https', 'ftp'):
            # Handle URL connection
            response = requests.get(x)
            content = response.content
            # R's read_xml handles encoding; lxml's parse/fromstring usually handles it via the byte stream
            doc = etree.fromstring(content, parser=parser)
            return etree.ElementTree(doc)
        else:
            # Handle local file path
            try:
                with open(x, 'rb') as f:
                    content = f.read()
                doc = etree.fromstring(content, parser=parser)
                return etree.ElementTree(doc)
            except (IOError, etree.XMLSyntaxError):
                if as_html:
                    # Fallback to HTML parsing if specified
                    with open(x, 'rb') as f:
                        content = f.read()
                    doc = etree.fromstring(content, parser=parser)
                    return etree.ElementTree(doc)
                raise
